cd /workspace && node -e "
const XLSX = require('xlsx');
const fs = require('fs');

const workbook = XLSX.readFile('testbed/data/order_summary.xlsx');
const lines = [];

workbook.SheetNames.forEach(sheetName => {
  lines.push('=== Sheet: ' + sheetName + ' ===');
  const sheet = workbook.Sheets[sheetName];
  const data = XLSX.utils.sheet_to_csv(sheet);
  lines.push(data);
  lines.push('');
});

const output = lines.join('\n');
console.log(output);

fs.writeFileSync('testbed/data/order_summary.csv', output);
console.log('--- Saved to testbed/data/order_summary.csv ---');
"
